/* selectProgram - Lee JiSeob */
SELECT
C.PROGRM_ID, C.PROGRM_NM, C.URL_ADDR, C.MENU_YN, C.UNITY_SRCH_YN, C.GROUP_PROGRM_ID, C.LAYOUT_SE_CD, C.FOLDER_NM, C.PROGRM_USE_SE_CD, C.MENU_COURS_NM, C.RM_CN, C.LGN_YN, C.GRIEF_THMA_SE_CD, C.USE_YN, C.ATFINO, C.FRST_RGTR_ID, C.FRST_REG_DT, C.LAST_MDFR_ID, C.LAST_MDFCN_DT
/* C.PROGRM_ID, C.UNT_SYS_SE_CD, (SELECT E.MENU_NM FROM PSA110 E * 메뉴 * WHERE TO_CHAR(E.MENU_ID) = C.UNT_SYS_SE_CD) AS UP_MENU_NM, C.PROGRM_NM, C.OUTSD_PROGRM_YN, C.URL_ADDR, C.PROGRM_USE_SE_CD, C.RM_CN, C.ATFINO, * (SELECT REAL_FILE_NM FROM SAB821 E WHERE C.ATFINO = E.ATFINO AND FILE_STTS_SE_CD != 'D') AS ATCMFL_NM, * C.ATCMFL_NM, C.FRST_RGTR_ID, C.FRST_REG_DT, C.LAST_MDFR_ID, C.LAST_MDFCN_DT */
FROM PSA100 C
/* LEFT JOIN PSA110 D ON TO_CHAR(D.MENU_ID) = C.UNT_SYS_SE_CD */
WHERE PROGRM_NM LIKE '%' || #{SEARCH} || '%' OR URL_ADDR LIKE '%' || #{SEARCH} || '%'
ORDER BY C.PROGRM_ID

mapper.insert:
SELECT PSA100_SQ01.NEXTVAL AS PROGRM_ID FROM DUAL
/* insertProgram Lee JiSeob */
INSERT INTO PSA100 ( PROGRM_ID, UNT_SYS_SE_CD, PROGRM_NM, OUTSD_PROGRM_YN, URL_ADDR, PROGRM_USE_SE_CD, RM_CN, ATFINO, ATCMFL_NM, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT ) VALUES ( #{PROGRM_ID}, #{UNT_SYS_SE_CD}, #{PROGRM_NM}, #{OUTSD_PROGRM_YN}, #{URL_ADDR}, #{PROGRM_USE_SE_CD}, #{RM_CN}, #{ATFINO}, #{ATCMFL_NM}, #{USER_ID}, SYSDATE, #{USER_ID}, SYSDATE )

mapper.delete:

/* deleteProgram Lee JiSeob */

DELETE PSA100
WHERE
	PROGRM_ID = #{PROGRM_ID}
